      await mkdir(settled, { recursive: true })
      const temporary = `${evidenceFile}.tmp`
      await writeFile(
        temporary,
        `${JSON.stringify({ launchId, sessionId, frontier, settledAt: Date.now() })}\n`,
        'utf8',
      )
