    if (evidenceFile === null) return
    try {
      await unlink(evidenceFile)
    } catch (cause) {
      if (cause?.code !== 'ENOENT') {
        logError(`could not invalidate settlement evidence: ${cause?.message ?? String(cause)}`)
      }
    }
  }

