 * The door a member's harness question tool opens onto the board, for
 * OpenCode's plugin, which loads it into OpenCode's own runtime (the native
 * cf has its own, in crates/cf-board). The plugin posts the questions as its
 * window's participant, waits for the chief to answer on the board, and
 * hands the answer back into the tool call, so nothing is typed into the
 * window. When the answer does not come in time, the door gives up and the
 * harness's own dialog takes over; when the window answered first, the
 * board's copy of the question gets that answer, so nobody answers it twice.
 *
 * The answer a poll finds is claimed for the door, and is received only once
 * the door says it handed it over (`acknowledge`): a door that never says so
 * leaves the answer to arrive a second time as text, and loses none. A poll
 * whose reply was lost is asked again, and gets the same claimed answer; a
 * receipt whose reply was lost is said again. A door the board shut (the task
 * was stopped) is refused with the words its model is to hear, which are
 * handed over as they are.
 */

/** How long a door waits for the board before the harness's own dialog takes over. */
const DOOR_WAIT_MS = 3_500_000
const POLL_WAIT_MS = 20_000
/**
 * How long a door waits before it asks again after a poll that got no answer,
 * once for each poll that failed in a row: the poll's reply may have been lost
 * on its way back, and the board gives the same claimed answer to the same
 * question again. A board that stays out of reach through all of them is
 * gone, and the harness's own dialog takes over.
 */
const POLL_RETRIES_MS = [250, 500, 1_000, 2_000]

/** A request to the board's API as the window's participant; `null` outside a window. */
export function boardClient({
  url = process.env.CONSENSFLOW_URL,
  token = process.env.CONSENSFLOW_TOKEN,
  fetch: fetchImpl = fetch,
} = {}) {
  if (typeof url !== 'string' || url.length === 0 || typeof token !== 'string') return null
  return async (method, path, body, { signal } = {}) => {
    const response = await fetchImpl(`${url}${path}`, {
      method,
      headers: { authorization: `Bearer ${token}`, 'content-type': 'application/json' },
      ...(body === undefined ? {} : { body: JSON.stringify(body) }),
      ...(signal === undefined ? {} : { signal }),
    })
    const value = await response.json().catch(() => ({}))
    if (!response.ok) {
      // Answered, and refused: not the same as a board that cannot be reached.
      throw Object.assign(new Error(value.message ?? `ConsensFlow answered ${response.status}`), {
        refused: true,
        code: value.error,
      })
    }
    return value
  }
}

/**
 * What a member's window tells its model when the board refuses its
 * question: nobody watches a member's window, so its own dialog would hold
 * the task for good. A door the board shut says in its own words that its
 * answer comes as a message, and those words go as they are.
 */
export const refusalReason = (cause) =>
  cause.code === 'door-closed'
    ? cause.message
    : `ConsensFlow could not put this question to the chief (${cause.message}). Ask with cf ask "…" instead.`

/**
 * Puts the questions on the board and waits for their answer: `{ id, answer }`,
 * the answer null when the wait ran out or `signal` ended it. `questions` are
 * in the board's shape: question, header, options (label, description), multiple.
 * A poll that gets no answer is asked again (`retries`, the pauses between
 * them); the question itself is put once, whatever comes of it.
 */
export async function askTheBoard(client, questions, { signal, retries = POLL_RETRIES_MS } = {}) {
  const { message } = await client('POST', '/api/questions', { questions })
  const until = Date.now() + DOOR_WAIT_MS
  let answer = null
  let lost = 0
  while (answer === null && Date.now() < until && !signal?.aborted) {
    const wait = Math.min(POLL_WAIT_MS, until - Date.now())
    try {
      answer = (
        await client('GET', `/api/questions/${message.id}?wait=${wait}`, undefined, { signal })
      ).answer
      lost = 0
    } catch (cause) {
      if (signal?.aborted) break
      // Answered, and refused: final. No answer at all: asked again.
      if (cause?.refused || lost >= retries.length) throw cause
      await new Promise((resolve) => setTimeout(resolve, retries[lost++]))
    }
  }
  return { id: message.id, answer }
}

/**
 * The door handed the answer it claimed to its harness, or could not: the board
 * is told so, which makes the answer received, or gives the claim back. What
 * the board says to it is of no use to a door that has done what it was for,
 * so a failure (a board of Node's, which knows no such route, included) is
 * not raised. A receipt that gets no answer at all (the board cannot be
 * reached) is said again, as a poll is (`retries`, the pauses between them):
 * the answer is in the harness's hands already, and one never received would
 * be pasted a second time and taken for the result. Said twice it does no
 * harm: the board takes an answer already read as read, and a claim already
 * given back as given back. An answer the board refused (the door was shut
 * meanwhile) is final.
 */
export async function acknowledge(client, answer, received, { retries = POLL_RETRIES_MS } = {}) {
  for (let lost = 0; ; lost += 1) {
    try {
      await client('POST', `/api/answers/${answer.id}/receipt`, { received })
      return
    } catch (cause) {
      if (cause?.refused || lost >= retries.length) return
      await new Promise((resolve) => setTimeout(resolve, retries[lost]))
    }
  }
}

/** The window answered first: the board's copy of the question takes that answer, from the asker. */
export const answerFromWindow = (client, id, choices) =>
  client('POST', '/api/answers', { question: id, choices })

import { createServer } from 'node:http'
import {
  acknowledge,
  answerFromWindow,
  askTheBoard,
  boardClient,
  refusalReason,
} from '../lib/question-door.js'

export const id = 'consensflow-session'
const SESSION = /^ses_[A-Za-z0-9]+$/
const refused = (error) => ({ ok: false, admitted: false, bytesWritten: 0, error })

/**
 * Whether OpenCode took a reply to its question tool: only then is the board's
 * answer received. By its SDK's contract a request that failed does not throw:
 * an HTTP error (a native 404 for a question that is gone), or a request that
 * got no response, resolves as a result with its `error` (`throwOnError` is
 * off), so a reply that resolved may be one that did not take. Throwing is
 * asked for, for the SDKs that honour it, and the result is read all the same:
 * it took when it holds no error and its response was a success, or it holds
 * the `true` the question's reply answers with (an SDK that answers with the
 * data alone says `true`, and nothing at all for an error).
 */
async function replied(client, input) {
  try {
    const result = await client.question.reply(input, { throwOnError: true })
    if (result === true) return true
    return result != null && !result.error && (result.response?.ok === true || result.data === true)
  } catch {
    return false
  }
}

/** This API runs inside the TUI: server-side session lists cannot prove its selected route. */
export async function tui(api, options) {
  const { launchId, port, token } =
    options ?? JSON.parse(process.env.CF_OPENCODE_SESSION_BRIDGE ?? '{}')
  if (
    typeof launchId !== 'string' ||
    !/^[A-Za-z0-9._-]+$/.test(launchId) ||
    !Number.isInteger(port) ||
    port < 1 ||
    port > 65535 ||
    typeof token !== 'string' ||
    token.length < 24
  )
    throw new Error('Invalid ConsensFlow session bridge configuration')
  const currentSession = () => {
    const route = api.route.current
    return route.name === 'session' && SESSION.test(route.params?.sessionID ?? '')
      ? route.params.sessionID
      : null
  }
  // The question tool's door in a member's window: the questions go to the
  // board as this window's participant, the board's answer comes back through
  // the API as the question's reply, and a reply given in the window first
  // goes to the board instead, so the question is answered once either way.
  // The chief's question stays in its window, where the human answers it.
  const board = process.env.CONSENSFLOW_PARTICIPANT === 'chief' ? null : boardClient()
  const held = new Map()
  const relay = async ({ id, sessionID, questions }) => {
    if (board === null || sessionID !== currentSession() || held.has(id)) return
    const control = new AbortController()
    held.set(id, control)
    try {
      const asked = await askTheBoard(
        board,
        questions.map((q) => ({
          question: q.question,
          header: q.header,
          options: q.options.map((o) => ({ label: o.label, description: o.description })),
          multiple: q.multiple === true,
        })),
        { signal: control.signal },
      )
      if (control.window !== undefined) {
        // An answer the board gave in the same moment was claimed and is not handed over.
        if (asked.answer !== null) await acknowledge(board, asked.answer, false)
        await answerFromWindow(board, asked.id, control.window)
      } else if (asked.answer !== null) {
        // Handed to the tool, then said so: the other way round, an answer would be lost.
        const handed = await replied(api.client, { requestID: id, answers: asked.answer.choices })
        await acknowledge(board, asked.answer, handed)
      }
    } catch (cause) {
      // Refused: the model hears why, as the answer. Not reached: the window's
      // own dialog stays.
      if (cause?.refused) {
        const reason = refusalReason(cause)
        await api.client.question
          .reply({ requestID: id, answers: questions.map(() => [reason]) })
          .catch(() => {})
      }
    } finally {
      held.delete(id)
    }
  }
  const settle = (requestID, answers) => {
    const control = held.get(requestID)
    if (control === undefined) return
    if (answers !== undefined) control.window = answers
    control.abort()
  }
  // OpenCode 1.18.31's TUI bus carries these under their plain names, with
  // the v2 shape its types describe under `question.v2.*`; both are heard.
  for (const suffix of ['', 'v2.']) {
    api.event?.on(`question.${suffix}asked`, (event) => void relay(event.properties))
    api.event?.on(`question.${suffix}replied`, (event) =>
      settle(event.properties.requestID, event.properties.answers),
    )
    api.event?.on(`question.${suffix}rejected`, (event) => settle(event.properties.requestID))
  }

  const server = createServer(async (request, response) => {
    const reply = (status, value) => {
      response.writeHead(status, {
        'content-type': 'application/json',
        'cache-control': 'no-store',
      })
      response.end(JSON.stringify(value))
    }
    if (request.headers.authorization !== `Bearer ${token}`) {
      request.resume()
      return reply(401, refused('unauthorized'))
    }
    if (request.method === 'GET' && request.url === '/session') {
      // What OpenCode says the shown conversation is doing: idle, busy, or
      // waiting to retry a refused request. A spent quota shows only here:
      // OpenCode writes nothing to its store while it waits for the reset.
      // No status is idle, as for delivery: it has not worked since the window opened.
      const sessionId = currentSession()
      const status =
        sessionId === null ? null : (api.state?.session?.status(sessionId) ?? { type: 'idle' })
      return reply(200, { launchId, sessionId, status })
    }
    if (request.method !== 'POST' || request.url !== '/deliver') {
      request.resume()
      return reply(404, refused('unknown-operation'))
    }
    let input
    try {
      let bytes = 0
      const chunks = []
      for await (const chunk of request) {
        bytes += chunk.length
        if (bytes > 128 * 1024) return reply(413, refused('request-too-large'))
        chunks.push(chunk)
      }
      input = JSON.parse(Buffer.concat(chunks).toString('utf8'))
    } catch {
      return reply(400, refused('invalid-request'))
    }
    if (
      input?.launchId !== launchId ||
      !SESSION.test(input?.sessionId ?? '') ||
      typeof input.text !== 'string' ||
      !input.text ||
      Buffer.byteLength(input.text) > 64 * 1024 ||
      !Number.isFinite(input.expiresAt)
    )
      return reply(400, refused('invalid-request'))
    if (input.expiresAt <= Date.now()) return reply(200, refused('expired'))
    // No await between reading the actual route and beginning native submission.
    if (currentSession() !== input.sessionId) return reply(200, refused('native-session-changed'))
    try {
      const result = await api.client.session.promptAsync(
        { sessionID: input.sessionId, parts: [{ type: 'text', text: input.text }] },
        { signal: AbortSignal.timeout(Math.min(3000, input.expiresAt - Date.now())) },
      )
      if (result.error || result.response?.status !== 204)
        throw new Error('native admission unknown')
      reply(200, { ok: true, admitted: true })
    } catch {
      // A started request can have reached the native server; never claim zero bytes.
      reply(200, { ok: false, admitted: null, error: 'uncertain' })
    }
  })
  server.requestTimeout = 3000
  server.headersTimeout = 3000
  await new Promise((resolve, reject) => {
    server.once('error', reject)
    server.listen(port, '127.0.0.1', resolve)
  })
  api.lifecycle.onDispose(async () => {
    await new Promise((resolve) => {
      server.close(resolve)
      server.closeAllConnections()
    })
  })
}

